/// <summary>
/// buildQueryRun method creates a QueryRun object that can be used to retrieve enum values and their labels.
/// </summary>
/// <param name = "_enumId">Enum Id value to be used on lookup. </param>
/// <param name = "_allowedValues">Container of allowed values to filter the lookup. </param>
/// <returns>QueryRun object containing enum values and labels. </returns>
internal static QueryRun buildQueryRun(EnumId _enumId, container _allowedValues = conNull())
{
    Query query = new Query();
    QueryBuildDataSource qbds = query.addDataSource(tableNum(METChargeThroughInvEnumLookupTmp));

    qbds.addSelectionField(fieldNum(METChargeThroughInvEnumLookupTmp, EnumValueLabelText));

    QueryRun queryRun = new QueryRun(query);

    queryRun.setCursor(METChargeThroughInvEnumLookupTmp::prepareData(_enumId, _allowedValues));

    return queryRun;
}

/// <summary>
/// Retrieves the label text corresponding to a specified enum value.
/// </summary>
/// <param name = "_dictEnum">The enum to lookup.</param>
/// <param name = "_value">The value of the enum.</param>
/// <returns>The label text for the enum value.</returns>
public static Description labelText(DictEnum _dictEnum, int _value)
{
    return _dictEnum.value2Label(_value);
}

/// <summary>
/// Prepares data for the METChargeThroughInvEnumLookupTmp table by inserting enum labels.
/// </summary>
/// <param name = "_enumId">The Id of the enum to prepare data for.</param>
/// <param name = "_allowedValues">Container of allowed values for filtering.</param>
/// <returns>The populated METChargeThroughInvEnumLookupTmp object.</returns>
internal static METChargeThroughInvEnumLookupTmp prepareData(EnumId _enumId, container _allowedValues = conNull())
{
    METChargeThroughInvEnumLookupTmp lookupTmp;
    DictEnum dictEnum = new DictEnum(_enumId);

    int i;

    boolean filterValues = _allowedValues != conNull();

    int maxIndex = filterValues? conLen(_allowedValues) : dictEnum.values() - 1;

    if (filterValues)
    {
        for (i = 1; i <= maxIndex; i++)
        {
            lookupTmp.EnumValueLabelText = METChargeThroughInvEnumLookupTmp::labelText(dictEnum, conPeek(_allowedValues, i));

            lookupTmp.insert();
        }
    }
    else
    {
        for (i = 0; i <= maxIndex; i++)
        {
            lookupTmp.EnumValueLabelText = METChargeThroughInvEnumLookupTmp::labelText(dictEnum, dictEnum.index2Value(i));

            lookupTmp.insert();
        }
    }

    return lookupTmp;
}
